#ifndef GUARD_TREY_WILD_H
#define GUARD_TREY_WILD_H

// TREY (TREY_PLAN.md 5.11, D22; Phase 4 chunk 4b-2): wild encounters by season, time of day and weather.
// Authored in docs/trey/wild_encounters.csv, generated by tools/trey/wild_csv.py into
// src/data/trey/wild_encounters_trey.h. Each map has a list of entries; each entry covers a set of seasons,
// times and weather groups (bit masks) and holds the tables for one or more areas (land, water, ...).
// - A map only in the CSV is strict: a combination no entry covers has no encounters.
// - A map that also has Emerald-style tables in wild_encounters.json: those count as "every season, every
//   weather" for their time of day, and CSV entries override them where they apply (area by area).

#include "constants/trey_wild.h"
#include "wild_encounter.h"

struct TreyWildEntry
{
    u8 seasons;   // bit per SEASON_*
    u8 times;     // bit per TIME_* (enum TimeOfDay)
    u8 weathers;  // bit per TREY_WEATHER_*
    u8 padding;
    const struct WildEncounterTypes *types;
};

struct TreyWildMap
{
    u8 mapGroup;
    u8 mapNum;
    u8 entryCount;
    u8 padding;
    const struct TreyWildEntry *entries;
};

extern const struct TreyWildMap gTreyWildMaps[];
extern const u16 gTreyWildMapCount;

u32 TreyWild_GetWeatherGroup(u32 weather);
u32 TreyWild_GetCurrentWeatherGroup(void);
// Index into gTreyWildMaps for a map, or 0xFFFF.
u16 TreyWild_FindMap(u8 mapGroup, u8 mapNum);
// The encounter tables for a wild header (gWildMonHeaders index, or TREY_WILD_HEADER_BASE + gTreyWildMaps
// index) under the given conditions. Never NULL; areas without encounters are NULL inside.
const struct WildEncounterTypes *TreyWild_GetTypesFor(u32 headerId, u32 timeOfDay, u32 season, u32 weatherGroup);
const struct WildEncounterTypes *TreyWild_GetTypes(u32 headerId, u32 timeOfDay); // current season and weather

#endif // GUARD_TREY_WILD_H
